import flask
from flask import Flask, request, jsonify, session
import sqlite3
import hashlib
import os
import hmac

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DB_PATH = os.environ.get('DB_PATH', '/var/lib/app/users.db')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        ts DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query with parameterized field but concatenated value for LIKE
    # Note: field is validated above so this is safe for field injection
    query = f"SELECT id, username, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile. Requires authentication."""
    auth_key = request.headers.get('X-API-Key')
    if not auth_key:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    requesting_user = db.execute(
        'SELECT * FROM users WHERE api_key = ?', (auth_key,)
    ).fetchone()

    if not requesting_user:
        return jsonify({'error': 'Invalid API key'}), 403

    user = db.execute(
        'SELECT id, username, role FROM users WHERE id = ?', (user_id,)
    ).fetchone()

    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/admin/export', methods=['POST'])
def export_data():
    """Export user data. Admin only."""
    auth_key = request.headers.get('X-API-Key')
    if not auth_key:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    admin = db.execute(
        'SELECT * FROM users WHERE api_key = ? AND role = ?',
        (auth_key, 'admin')
    ).fetchone()

    if not admin:
        return jsonify({'error': 'Admin access required'}), 403

    fmt = request.json.get('format', 'json') if request.json else 'json'

    users = db.execute('SELECT id, username, role FROM users').fetchall()

    db.execute('INSERT INTO audit_log (action, user_id, details) VALUES (?, ?, ?)',
               ('export', admin['id'], f'format={fmt}'))
    db.commit()

    return jsonify({'users': [dict(u) for u in users], 'count': len(users)})

@app.route('/api/health', methods=['GET'])
def health():
    """Health check endpoint."""
    try:
        db = get_db()
        db.execute('SELECT 1').fetchone()
        return jsonify({'status': 'healthy', 'db': 'connected'})
    except:
        return jsonify({'status': 'degraded', 'db': 'disconnected'}), 503

@app.before_request
def log_request():
    if request.endpoint and request.endpoint != 'health':
        app.logger.info(f"{request.method} {request.path} from {request.remote_addr}")

if __name__ == '__main__':
    init_db()
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    app.run(host='0.0.0.0', port=8080, debug=debug_mode)
